import base64
import hashlib

def decode_and_hash():
    # Using a triple-quoted string to hold the massive Base64 block.
    # .replace() and .split() ensure we strip any accidental newlines/spaces 
    # from the source code formatting.
    encoded_source = """

    """.strip().replace("\n", "").replace("\r", "").replace(" ", "")

    try:
        # 1. Decode Base64 to string
        decoded_bytes = base64.b64decode(encoded_source)
        decoded_string = decoded_bytes.decode('utf-8')
        
        # 2. Generate SHA-256 Hash
        sha256_hash = hashlib.sha256(decoded_string.encode('utf-8')).hexdigest()

        print("--- Decoded Java Source ---")
        print(decoded_string)
        print("---------------------------")
        print(f"Code Hash: {sha256_hash}")
        
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    decode_and_hash()